def validate_role_model_policy(policy: dict[str, Any], profiles: list[dict[str, Any]]) -> None:
    required = policy.get("required_operational_profiles")
    observed = [item["profile_id"] for item in profiles]
    if required != list(PROFILE_IDS):
        raise ValueError(f"behavioral-diversity policy profile inventory differs:{required}")
    if observed != list(PROFILE_IDS):
        raise ValueError(f"offline role-model profile inventory differs:{observed}")
    if len(set(observed)) != 4:
        raise ValueError("offline role-model profile IDs are not unique")


def build(repo: Path) -> str:
    spec = json.loads((repo / SPEC).read_text(encoding="utf-8"))
    snapshot = json.loads((repo / SNAPSHOT).read_text(encoding="utf-8"))
    truth = json.loads((repo / TRUTH).read_text(encoding="utf-8"))
    manifest = json.loads((repo / MANIFEST).read_text(encoding="utf-8"))
    policy = json.loads((repo / ROLE_MODEL_POLICY).read_text(encoding="utf-8"))
    profiles = role_model_profiles()
    validate_role_model_policy(policy, profiles)
    evolution = load_evolution(repo)
    role_model_contract = {
        "schema_version": "1.0.0",
        "profile_family": PROFILE_FAMILY,
        "selection_profile": PROFILE_SELECTION,
        "playable_profile_count": len(profiles),
        "default_profile_id": DEFAULT_PROFILE_ID,
        "required_profile_ids": list(PROFILE_IDS),
        "source_policy_path": ROLE_MODEL_POLICY.as_posix(),
        "source_policy_sha256": sha_file(repo / ROLE_MODEL_POLICY),
        "clinical_authority": "NOT_GRANTED",
        "operational_timing": "NOT_CALIBRATED",
        "scoring_state": "SOURCE_CONFORMANCE_ONLY",
    }
    role_model_contract = with_hash(role_model_contract, "contract_sha256")
    payload = {
        "schema_version": "1.2.0",
        "release_id": evolution["policy"]["release_id"],
        "standalone_mode": "single_file_no_network",
        "authority": spec["authority"],
        "spec": spec,
        "source_snapshot": snapshot,
        "source_truth": truth,
        "example_manifest": manifest,
        "scenario_evolution": evolution_binding(evolution),
        "role_model_profile_contract": role_model_contract,
        "default_role_model_profile_id": DEFAULT_PROFILE_ID,
        "role_model_profiles": profiles,
        "open_validity_obligations": OPEN,
        "provenance": {
            "spec_path": SPEC.as_posix(),
            "spec_file_sha256": sha_file(repo / SPEC),
            "snapshot_path": SNAPSHOT.as_posix(),
            "snapshot_file_sha256": sha_file(repo / SNAPSHOT),
            "source_truth_path": TRUTH.as_posix(),
            "source_truth_file_sha256": sha_file(repo / TRUTH),
            "example_manifest_path": MANIFEST.as_posix(),
            "example_manifest_file_sha256": sha_file(repo / MANIFEST),
            "role_model_policy_path": ROLE_MODEL_POLICY.as_posix(),
            "role_model_policy_sha256": sha_file(repo / ROLE_MODEL_POLICY),
            "role_model_contract_sha256": role_model_contract["contract_sha256"],
            "role_model_profiles_root_sha256": sha_bytes(canon(profiles)),
            "engine_sha256": sha_bytes(ENGINE.encode("utf-8")),
            "ui_sha256": sha_bytes(UI.encode("utf-8")),
            "css_sha256": sha_bytes(CSS.encode("utf-8")),
        },
    }
    payload["provenance"]["payload_sha256"] = sha_bytes(canon(payload))
    data = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).replace("</script>", r"<\/script>")
    return TEMPLATE.replace("__CSS__", CSS).replace("__DATA__", data).replace("__ENGINE__", ENGINE).replace("__UI__", UI)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", type=Path, default=Path("."))
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    repo = args.repo.resolve()
    expected = build(repo)
    target = repo / TARGET
    if args.check:
        ok = target.is_file() and target.read_text(encoding="utf-8") == expected
        print(json.dumps({
            "schema_version": "1.1.0",
            "status": "PASS" if ok else "FAIL",
            "mode": "check",
            "target": TARGET.as_posix(),
            "target_sha256": sha_bytes(expected.encode("utf-8")),
            "bytes": len(expected.encode("utf-8")),
            "playable_role_model_profiles": len(role_model_profiles()),
            "mismatches": [] if ok else [TARGET.as_posix()],
        }, indent=2, sort_keys=True))
        return 0 if ok else 3
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(expected, encoding="utf-8", newline="\n")
    print(json.dumps({
        "schema_version": "1.1.0",
        "status": "PASS",
        "mode": "write",
        "target": TARGET.as_posix(),
        "target_sha256": sha_file(target),
        "bytes": target.stat().st_size,
        "playable_role_model_profiles": len(role_model_profiles()),
    }, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
